CREATE TABLE `os_banner` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `category` int(11) NOT NULL COMMENT 'Category',
  `title` varchar(255) CHARACTER SET utf8 NOT NULL COMMENT 'Title',
  `banner` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Banner',
  `clickurl` varchar(255) CHARACTER SET utf8 DEFAULT NULL COMMENT 'Click URL',
  `details` text CHARACTER SET utf8 DEFAULT NULL COMMENT 'Details',
  `status` enum('Active','Inactive') COLLATE utf8_unicode_ci DEFAULT 'Active' COMMENT 'Status',
  `sticky` enum('Yes','No') COLLATE utf8_unicode_ci DEFAULT 'No' COMMENT 'Sticky',
  `ordering` int(11) DEFAULT 0 COMMENT 'Ordering',
  `created_by` int(11) DEFAULT NULL COMMENT 'Created By',
  `created_on` timestamp NULL DEFAULT NULL COMMENT 'Created On',
  PRIMARY KEY (`id`),
  KEY `category` (`category`),
  CONSTRAINT `os_banner_ibfk_1` FOREIGN KEY (`category`) REFERENCES `os_banner_category` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

