/*Table structure for table `os_customer` */

DROP TABLE IF EXISTS `os_customer`;

CREATE TABLE `os_customer` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `full_name` varchar(150) NOT NULL COMMENT 'Name',
  `username` varchar(100) NOT NULL COMMENT 'Username',
  `email` varchar(100) NOT NULL COMMENT 'Email',
  `password` varchar(100) NOT NULL COMMENT 'Password',
  `register_date` timestamp NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Register Date',
  `lastvisit` datetime DEFAULT '0000-00-00 00:00:00' COMMENT 'Last Visit',
  `activation` varchar(100) DEFAULT NULL COMMENT 'Activation',
  `group` int(11) DEFAULT NULL COMMENT 'Group',
  `status` int(1) DEFAULT 1 COMMENT 'Status',
  PRIMARY KEY (`id`),
  KEY `idx_name` (`full_name`),
  KEY `username` (`username`),
  KEY `email` (`email`),
  KEY `status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1001 DEFAULT CHARSET=utf8;

/*Data for the table `os_customer` */

/*Table structure for table `os_district` */

DROP TABLE IF EXISTS `os_district`;

CREATE TABLE `os_district` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `country` int(11) NOT NULL DEFAULT 18 COMMENT 'Country',
  `state` int(11) NOT NULL COMMENT 'State',
  `city` int(11) NOT NULL COMMENT 'City',
  `title` varchar(150) COLLATE utf8_unicode_ci NOT NULL COMMENT 'District',
  `status` enum('Active','Inactive') COLLATE utf8_unicode_ci NOT NULL DEFAULT 'Active' COMMENT 'Status',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

