/*Table structure for table `os_document` */

DROP TABLE IF EXISTS `os_document`;

CREATE TABLE `os_document` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `category` int(11) NOT NULL COMMENT 'Category',
  `title` varchar(255) CHARACTER SET utf8 NOT NULL COMMENT 'Title',
  `document_file` varchar(255) CHARACTER SET utf8 DEFAULT NULL COMMENT 'Document',
  `document_type` varchar(50) CHARACTER SET utf8 DEFAULT NULL COMMENT 'Type',
  `document_size` varchar(50) CHARACTER SET utf8 DEFAULT NULL COMMENT 'Size',
  `details` text CHARACTER SET utf8 DEFAULT NULL COMMENT 'Details',
  `status` enum('Active','Inactive') COLLATE utf8_unicode_ci DEFAULT 'Active' COMMENT 'Status',
  `created_by` int(11) DEFAULT NULL COMMENT 'Created By',
  `created_on` timestamp NULL DEFAULT NULL COMMENT 'Created On',
  PRIMARY KEY (`id`),
  KEY `cetegory` (`category`),
  CONSTRAINT `os_document_ibfk_1` FOREIGN KEY (`category`) REFERENCES `os_document_category` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

/*Data for the table `os_document` */

/*Table structure for table `os_document_category` */

DROP TABLE IF EXISTS `os_document_category`;

CREATE TABLE `os_document_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent` int(11) DEFAULT NULL COMMENT 'Parent',
  `title` varchar(255) NOT NULL COMMENT 'Title',
  `details` text DEFAULT NULL COMMENT 'Details',
  `alias` varchar(255) DEFAULT NULL COMMENT 'Alias',
  `path` varchar(255) DEFAULT NULL COMMENT 'Path',
  `status` enum('Active','Inactive') DEFAULT 'Active' COMMENT 'Status',
  `created_by` int(11) DEFAULT NULL COMMENT 'Created By',
  `created_on` timestamp NULL DEFAULT NULL COMMENT 'Created On',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8;

