/*Table structure for table `os_thana` */

DROP TABLE IF EXISTS `os_thana`;

CREATE TABLE `os_thana` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `country` int(11) NOT NULL DEFAULT 18 COMMENT 'Country',
  `state` int(11) NOT NULL COMMENT 'State',
  `city` int(11) NOT NULL COMMENT 'City',
  `district` int(11) NOT NULL COMMENT 'District',
  `title` varchar(100) COLLATE utf8_unicode_ci NOT NULL COMMENT 'Thana',
  `status` enum('Active','Inactive') COLLATE utf8_unicode_ci NOT NULL DEFAULT 'Active' COMMENT 'Status',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=528 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

