/*Table structure for table `os_user` */

DROP TABLE IF EXISTS `os_user`;

CREATE TABLE `os_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `full_name` varchar(150) NOT NULL COMMENT 'Name',
  `username` varchar(100) NOT NULL COMMENT 'Username',
  `email` varchar(100) NOT NULL COMMENT 'Email',
  `password` varchar(100) NOT NULL COMMENT 'Password',
  `register_date` timestamp NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Register Date',
  `lastvisit` datetime DEFAULT '0000-00-00 00:00:00' COMMENT 'Last Visit',
  `activation` varchar(100) DEFAULT NULL COMMENT 'Activation',
  `group_id` int(11) DEFAULT NULL COMMENT 'Group',
  `status` int(1) DEFAULT 1 COMMENT 'Status',
  `picture` varchar(255) DEFAULT NULL COMMENT 'Picture',
  `photo` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_name` (`full_name`),
  KEY `username` (`username`),
  KEY `email` (`email`),
  KEY `status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1002 DEFAULT CHARSET=utf8;

/*Data for the table `os_user` */

insert  into `os_user`(`id`,`full_name`,`username`,`email`,`password`,`register_date`,`lastvisit`,`activation`,`group_id`,`status`,`picture`,`photo`) values (1,'Saidur Rahman','admin','info@saidur-rahman.com','d033e22ae348aeb5660fc2140aec35850c4da997','2013-04-04 23:18:41','2019-09-20 08:25:56','',1,1,NULL,'1428917653_rana.jpg');

/*Table structure for table `os_user_group` */

DROP TABLE IF EXISTS `os_user_group`;

CREATE TABLE `os_user_group` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `group_type` enum('Front','Back') NOT NULL DEFAULT 'Front' COMMENT 'Type',
  `title` varchar(150) NOT NULL COMMENT 'Title',
  `details` text DEFAULT NULL COMMENT 'Details',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_usergroup_parent_title_lookup` (`title`),
  KEY `idx_usergroup_title_lookup` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8;

/*Data for the table `os_user_group` */

insert  into `os_user_group`(`id`,`group_type`,`title`,`details`) values (1,'Back','Super Users',NULL),(2,'Back','Administrator',NULL),(3,'Back','Manager',NULL),(4,'Back','Publisher',NULL),(5,'Back','Editor',NULL),(6,'Back','Author',NULL),(7,'Front','Registered',NULL);

/*Table structure for table `os_user_status` */

DROP TABLE IF EXISTS `os_user_status`;

CREATE TABLE `os_user_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(100) CHARACTER SET latin1 NOT NULL COMMENT 'Status',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

/*Data for the table `os_user_status` */

insert  into `os_user_status`(`id`,`title`) values (1,'Active'),(2,'Not Active'),(3,'Blocked'),(4,'Expired'),(5,'Invalid');

/*Table structure for table `os_visitor` */

DROP TABLE IF EXISTS `os_visitor`;

CREATE TABLE `os_visitor` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_type` tinyint(1) DEFAULT NULL COMMENT 'User Type',
  `user_id` int(11) DEFAULT NULL COMMENT 'User',
  `user_name` varchar(100) CHARACTER SET latin1 DEFAULT NULL COMMENT 'Username',
  `page_title` varchar(255) CHARACTER SET utf8 DEFAULT NULL COMMENT 'Page Title',
  `page_link` varchar(150) CHARACTER SET utf8 DEFAULT NULL COMMENT 'Page Link',
  `server_time` timestamp NULL DEFAULT NULL COMMENT 'Server Time',
  `browser` varchar(100) CHARACTER SET utf8 DEFAULT NULL COMMENT 'Browser',
  `visitor_ip` varchar(100) CHARACTER SET utf8 DEFAULT NULL COMMENT 'IP',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

/*Data for the table `os_visitor` */

/*Table structure for table `os_yiisession` */

DROP TABLE IF EXISTS `os_yiisession`;

CREATE TABLE `os_yiisession` (
  `id` char(32) COLLATE utf8_unicode_ci NOT NULL COMMENT 'ID',
  `expire` int(11) DEFAULT NULL COMMENT 'Expire',
  `data` longblob DEFAULT NULL COMMENT 'Data',
  `userId` int(11) DEFAULT NULL COMMENT 'UID',
  `userType` tinyint(1) DEFAULT NULL COMMENT 'User Type',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

